#include "fractal/protocol_security.h"
#include "fake_tls.h"
#include <stdio.h>
#define CHECK(x) do{if(!(x)){printf("fail %s:%d: %s\n",__FILE__,__LINE__,#x);return 1;}}while(0)
static fractal_security_policy good(void){fractal_security_policy p={true,false,FRACTAL_TLS_VERSION_TLS13,FRACTAL_CIPHER_TLS_AES_256_GCM_SHA384,false,false,true,false,true};return p;}
int main(void){fractal_security_policy p=good();CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_ACCEPTED);p=good();p.cleartext=true;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_CLEARTEXT);p=good();p.tls_version=12;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_TLS_VERSION);p=good();p.zero_rtt=true;p.mutating_intent=true;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_ZERO_RTT_MUTATION);p=good();p.cipher=99;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_CIPHER);p=good();p.service_identity_present=false;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_MISSING_SERVICE_IDENTITY);p=good();p.service_key_replaced_without_rotation=true;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_SERVICE_KEY_REPLACEMENT);p=good();p.credential_proof_present=false;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_UNPROVED_CREDENTIAL);fractal_cbor_map m={{{1,1},{2,300},{3,5}},3};uint8_t cbor[64];uint32_t n=0;CHECK(fractal_cbor_encode_uint_map(&m,cbor,sizeof(cbor),&n)==FRACTAL_OK);CHECK(n==9&&cbor[0]==0xa3&&cbor[1]==1&&cbor[2]==1&&cbor[3]==2&&cbor[4]==0x19&&cbor[5]==1&&cbor[6]==0x2c&&cbor[7]==3&&cbor[8]==5);fractal_cbor_map out;CHECK(fractal_cbor_decode_uint_map(cbor,n,&out,true)==FRACTAL_OK);CHECK(out.count==3&&out.fields[1].value==300);CHECK(fractal_protocol_semantic_identity(&m)==fractal_protocol_semantic_identity(&out));uint8_t dup[]={0xa2,1,1,1,2};CHECK(fractal_cbor_decode_uint_map(dup,sizeof(dup),&out,true)==FRACTAL_ERROR_INVALID_ARGUMENT);uint8_t nondet[]={0xa1,0x18,1,1};CHECK(fractal_cbor_decode_uint_map(nondet,sizeof(nondet),&out,true)==FRACTAL_ERROR_INVALID_ARGUMENT);uint8_t indef[]={0xbf,1,1,0xff};CHECK(fractal_cbor_decode_uint_map(indef,sizeof(indef),&out,true)==FRACTAL_ERROR_INVALID_ARGUMENT);uint8_t trailing[]={0xa1,1,1,0};CHECK(fractal_cbor_decode_uint_map(trailing,sizeof(trailing),&out,true)==FRACTAL_ERROR_INVALID_ARGUMENT);uint8_t req[]={0xa1,0x19,3,0xe8,1};CHECK(fractal_cbor_decode_uint_map(req,sizeof(req),&out,true)==FRACTAL_ERROR_INVALID_ARGUMENT);CHECK(fractal_cbor_decode_uint_map(req,sizeof(req),&out,false)==FRACTAL_OK);fractal_protocol_frame_header h={FRACTAL_PROTOCOL_FRAME_MAGIC,FRACTAL_PROTOCOL_FRAME_VERSION,FRACTAL_FRAME_COMPATIBILITY,0,n,42};uint8_t frame[128];uint32_t written;const uint8_t*payload;fractal_protocol_frame_header dh;CHECK(fractal_frame_encode(h,cbor,frame,sizeof(frame),&written)==FRACTAL_OK);CHECK(fractal_frame_decode(frame,written,&dh,&payload)==FRACTAL_OK&&dh.payload_length==n&&payload[0]==0xa3);CHECK(fractal_frame_decode(frame,written+1,&dh,&payload)==FRACTAL_ERROR_INVALID_ARGUMENT);h.payload_length=FRACTAL_PROTOCOL_MAX_PAYLOAD+1;CHECK(fractal_frame_encode(h,cbor,frame,sizeof(frame),&written)==FRACTAL_ERROR_INVALID_ARGUMENT);fractal_fake_tls tls;fractal_fake_tls_init(&tls);CHECK(!fractal_fake_tls_can_write_application_data(&tls));CHECK(fractal_fake_tls_handshake(&tls,good())==FRACTAL_SECURITY_ACCEPTED);CHECK(fractal_fake_tls_can_write_application_data(&tls));return 0;}
